def parse_csv_line(line):
    fields = []
    current = []
    in_quotes = False
    i = 0
    length = len(line)
    while i < length:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Check for escaped quote
                if i + 1 < length and line[i + 1] == '"':
                    current.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                current.append(ch)
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        i += 1
    fields.append(''.join(current))
    return fields
